import { describe, expect, it } from 'vitest'
import { convert } from './converter'

/**
 * Regression tests. Expected values were generated by the converter itself
 * (the author considers its current behaviour correct) from words of the Book of Genesis.
 * If a test fails after a rule change, check that the change is intended.
 */
describe('convert: single words', () => {
  it.each([
    ['בְּרֵאשִׁית', 'bereszit'],
    ['בָּרָא', 'bara'],
    ['אֱלֹהִים', 'elohim'],
    ['אֵת', 'et'],
    ['הַשָּׁמַיִם', 'haszamajim'],
    ['וְאֵת', 'weet'],
    ['הָאָרֶץ', 'haarec'],
    ['וַיֹּאמֶר', 'wajomer'],
    ['כִּי', 'ki'],
    ['טוֹב', 'tow'],
    ['לֹא', 'lo'],
    ['זֶה', 'ze'],
    ['סֵפֶר', 'sefer'],
    ['תּוֹלְדֹת', 'toldot'],
    ['הִנֵּנִי', 'hineni'],
    ['בְּנוֹ', 'beno'],
    ['הַגָּדֹל', 'hagadol'],
    ['וַיִּקְרָא', 'wajikra'],
    ['בְּיוֹם', 'bejom'],
    ['עֵינָיו', 'ejnaw'],
  ])('%s -> %s', (hebrew, phonetics) => {
    expect(convert(hebrew)).toBe(phonetics)
  })

  it('reads the Tetragrammaton as "adonai"', () => {
    expect(convert('יְהוָה')).toBe('adonai')
  })
})

describe('convert: phrases', () => {
  it('separates words with a single space and drops punctuation', () => {
    expect(convert('בְּרֵאשִׁית, בָּרָא אֱלֹהִים, אֵת הַשָּׁמַיִם, וְאֵת הָאָרֶץ.')).toBe(
      'bereszit bara elohim et haszamajim weet haarec',
    )
  })

  it('treats maqaf (hyphen) as a word separator', () => {
    expect(convert('כִּי-טוֹב')).toBe('ki tow')
  })

  it('returns an empty string for text without Hebrew letters', () => {
    expect(convert('abc 123')).toBe('')
  })
})
